import type { Career } from '../types';
import { ApiError, api } from './api';
import { coreApi, type ApiCareerInput, type ApiCareerModel } from './coreApi';
import { careerIntelligenceService } from './careerIntelligence';

// A career draft the user reviews before anything is saved. `source` says honestly where it came from:
//   'ai'       generated by the server's AI provider (unverified)
//   'template' the built-in keyword template (NOT AI; generic, not tailored)
export interface DraftSkill { name: string; description: string; requiredLevel: number; importance: number; evidenceExpectation: string }
export interface DraftCapability { name: string; description: string; skills: DraftSkill[] }
export interface DraftModel { name: string; category: string; description: string; capabilities: DraftCapability[] }
export interface DraftProvider { id: string; label: string; model: string }
export interface DraftState { source: 'ai' | 'template'; provider: DraftProvider | null; model: DraftModel }
export interface DraftRequest { name: string; category: string; description: string }
interface ApiDraft { source: 'ai'; unverified: true; provider: DraftProvider; draft: { name: string; description: string; capabilities: DraftCapability[] } }

export const SOURCE_LABEL = { ai: 'AI-generated draft · unverified', template: 'Template fallback · not AI-generated' } as const;
export const EVIDENCE_PREFIX = 'Evidence to show: ';

// Asks the server's AI provider. Never falls back to the template by itself: any failure is thrown to the caller, which shows it.
export async function requestAiDraft(input: DraftRequest): Promise<DraftState> {
  const r = await api.post<ApiDraft>('/careers/draft', input);
  return { source: 'ai', provider: r.provider, model: { name: r.draft.name, category: input.category.trim() || 'Other', description: r.draft.description, capabilities: r.draft.capabilities } };
}

// The existing keyword-template analyser, wrapped so it can use the same review screen. Only used when the user explicitly chooses it.
export async function templateDraft(input: DraftRequest): Promise<DraftState> {
  const c: Career = await careerIntelligenceService.generateCareerModel({ name: input.name, field: input.category, description: input.description });
  return {
    source: 'template', provider: null,
    model: {
      name: c.name, category: c.category || 'Other', description: c.description,
      capabilities: c.capabilities.map((k) => ({ name: k.name, description: k.description ?? '', skills: k.skills.map((s) => ({ name: s.name, description: s.description ?? '', requiredLevel: s.requiredLevel, importance: 3, evidenceExpectation: '' })) })),
    },
  };
}

export function friendlyDraftError(e: unknown): string {
  if (!(e instanceof ApiError)) return 'The draft could not be created. Nothing was saved.';
  switch (e.code) {
    case 'ai_not_configured': return 'AI drafting is not set up on this server. You can use the template instead, which is generic and not AI-generated.';
    case 'ai_timeout': return 'The AI model took too long. Nothing was saved. Try again, or use the template instead.';
    case 'ai_unavailable': return 'The AI model could not draft this career right now. Nothing was saved. Try again later, or use the template instead.';
    case 'ai_invalid_output': return 'The AI returned a draft that did not pass our checks, so it was discarded. Nothing was saved. Try again, or use the template instead.';
    case 'rate_limited': return 'You are asking too quickly. Wait a few seconds and try again.';
    case 'network_error': return "Couldn't reach the server. Check that the API is running, then try again.";
    case 'timeout': return 'The server took too long to answer. Please try again.';
    case 'token_expired': case 'invalid_token': case 'token_missing': return 'Your session has ended. Please sign in again.';
    default: return e.status === 400 ? 'Check the career name, field and description, then try again.' : 'The draft could not be created. Nothing was saved.';
  }
}

// Checks run in the editor before save; the server validates again and is the authority.
export function draftProblems(m: DraftModel): string[] {
  const out: string[] = [];
  if (!m.name.trim()) out.push('Give the career a name.');
  if (m.capabilities.length < 1) out.push('Keep at least one capability.');
  if (m.capabilities.length > 12) out.push('Use at most 12 capabilities.');
  const seen = new Set<string>();
  let total = 0;
  m.capabilities.forEach((c, i) => {
    if (!c.name.trim()) out.push(`Capability ${i + 1} needs a name.`);
    if (c.skills.length < 1) out.push(`“${c.name.trim() || `Capability ${i + 1}`}” needs at least one skill.`);
    if (c.skills.length > 12) out.push(`“${c.name.trim()}” has more than 12 skills.`);
    total += c.skills.length;
    c.skills.forEach((s) => {
      if (!s.name.trim()) out.push(`A skill in “${c.name.trim() || `Capability ${i + 1}`}” needs a name.`);
      const k = s.name.trim().toLowerCase();
      if (k && seen.has(k)) out.push(`“${s.name.trim()}” appears twice. Skill names must be unique.`);
      seen.add(k);
      if (!Number.isInteger(s.requiredLevel) || s.requiredLevel < 1 || s.requiredLevel > 5) out.push(`“${s.name.trim()}” needs a level from 1 to 5.`);
    });
  });
  if (total > 60) out.push('Use at most 60 skills in total.');
  return out;
}

// What is stored: the existing career fields plus skills.description. There is no per-skill evidence column, so each skill's evidence
// expectation is appended to its description under an explicit label rather than silently dropped.
export function draftToApiInput(m: DraftModel): ApiCareerInput {
  const text = (s: string, max: number) => s.replace(/\s+/g, ' ').trim().slice(0, max);
  return {
    name: text(m.name, 120), category: text(m.category, 60) || 'Other', description: text(m.description, 1000), evidenceExpectations: [],
    capabilities: m.capabilities.map((c) => ({
      name: text(c.name, 100), description: text(c.description, 500),
      skills: c.skills.map((s) => {
        const ev = text(s.evidenceExpectation, 200);
        return { name: text(s.name, 100), requiredLevel: s.requiredLevel, importance: s.importance >= 1 && s.importance <= 5 ? s.importance : 3, description: [text(s.description, 300), ev ? `${EVIDENCE_PREFIX}${ev}` : ''].filter(Boolean).join('\n\n') };
      }),
    })),
  };
}

// Only ever called after the user has pressed the explicit confirmation button. Uses the existing authenticated create route.
export async function saveDraft(m: DraftModel): Promise<ApiCareerModel> {
  const problems = draftProblems(m);
  if (problems.length) throw new Error(problems[0]);
  return coreApi.createCareer(draftToApiInput(m));
}
